(SELECT STRING_AGG(CONVERT(nvarchar(max),CONCAT(OBJECT_NAME(c.object_id),N''|'',c.column_id,N''|'',c.name,N''|'',TYPE_NAME(c.user_type_id),N''|'',c.max_length,N''|'',c.precision,N''|'',c.scale,N''|'',c.is_nullable,N''|'',c.is_identity,N''|'',COALESCE(OBJECT_DEFINITION(c.default_object_id),N''''))),N'';'') WITHIN GROUP(ORDER BY OBJECT_NAME(c.object_id),c.column_id) FROM sys.columns c WHERE c.object_id IN(OBJECT_ID(N''dbo.work_finops_scope''),OBJECT_ID(N''dbo.work_finops_receipts''),OBJECT_ID(N''dbo.work_finops_manifest''),OBJECT_ID(N''dbo.work_supplier_payment_requests''))),
