IF NOT EXISTS(SELECT 1 FROM dbo.work_finops_scope s JOIN dbo.products p ON p.id=s.product_id JOIN dbo.work_finops_receipts r ON r.id=s.receipt_id JOIN dbo.purchase_invoices v ON v.id=s.invoice_id WHERE s.currency=N''TRY'' AND p.stock_code=N''TEST-DAILY-FINOPS-20261006'' AND p.name=N''Deneme kaydı — Finans ödeme ürünü'' AND p.unit=N''ADET'' AND p.currency_code=N''TRY'' AND p.current_stock_qty=5 AND p.average_cost_try=60 AND p.purchase_price=60 AND p.sales_price=0 AND p.supplier_id=s.supplier_id AND p.is_active=1 AND p.is_deleted=0 AND p.source_record_key IS NULL AND p.migration_run_id IS NULL AND r.product_id=p.id AND r.supplier_id=s.supplier_id AND r.quantity=5 AND r.unit=N''ADET'' AND r.unit_factor=1 AND r.unit_cost_try=60 AND r.state=N''accepted'' AND v.document_no=N''TDAY-FINOPS-20261006'' AND v.supplier_id=s.supplier_id AND v.status=N''finalized'' AND v.document_currency=N''TRY'' AND v.supplier_currency=N''TRY'' AND v.account_currency=N''TRY'' AND v.document_date=CONVERT(date,N''2026-10-06'') AND v.subtotal=300 AND v.grand_total=300 AND v.amount_try=300 AND v.account_amount=300 AND v.exchange_rate_snapshot=1 AND v.account_exchange_rate_snapshot=1 AND v.discount_total=0 AND v.is_migrated=0 AND v.source_record_key IS NULL AND v.migration_run_id IS NULL AND v.created_by=16 AND v.finalized_at IS NOT NULL AND (SELECT COUNT(*) FROM dbo.purchase_invoice_items WHERE purchase_invoice_id=v.id)=1 AND EXISTS(SELECT 1 FROM dbo.purchase_invoice_items i WHERE i.purchase_invoice_id=v.id AND i.product_id=p.id AND i.stock_code_snapshot=p.stock_code AND i.product_name_snapshot=p.name AND i.quantity=5 AND i.purchase_price=60 AND i.currency_code=N''TRY'' AND i.line_total=300 AND i.line_total_try=300 AND i.stock_effect_snapshot=N''goods_receipt_already_posted'' AND i.source_record_key IS NULL AND i.migration_run_id IS NULL) AND (SELECT COUNT(*) FROM dbo.stock_movements WHERE product_id=p.id)=1 AND (SELECT COUNT(*) FROM dbo.stock_movements WHERE source_type=N''goods_receipt'' AND source_id=r.id)=1 AND EXISTS(SELECT 1 FROM dbo.stock_movements m WHERE m.product_id=p.id AND m.source_type=N''goods_receipt'' AND m.source_id=r.id AND m.quantity_in=5 AND m.quantity_out=0 AND m.quantity_net=5 AND m.unit_cost_try=60 AND m.average_cost_try_after=60 AND m.amount_try=300 AND m.created_by=16) AND EXISTS(SELECT 1 FROM dbo.supplier_movements m WHERE m.supplier_id=s.supplier_id AND m.purchase_invoice_id=v.id AND m.movement_type=N''purchase_invoice'' AND m.amount=300 AND m.balance_effect=300 AND m.account_currency=N''TRY'' AND m.account_amount=300 AND m.amount_try=300 AND m.document_exchange_rate_snapshot=1 AND m.account_exchange_rate_snapshot=1 AND m.created_by=16)) THROW 51230,''WORK_PAYMENT_SOURCE_UNAVAILABLE'',1;
IF NOT EXISTS(SELECT 1 FROM dbo.test_daily_scope d JOIN dbo.work_finops_scope s ON s.currency=N''TRY'' WHERE d.flow=N''finops-20261006'' AND d.product_id=s.product_id AND d.supplier_id=s.supplier_id AND d.customer_id IS NULL AND d.source_id=s.invoice_id AND d.source_kind=N''purchase'' AND d.settings_json=N''{"prepared":true,"runId":"ERP-FINOPS-20261006"}'') THROW 51230,''WORK_PAYMENT_SOURCE_UNAVAILABLE'',1;
IF EXISTS(SELECT 1 FROM dbo.work_finops_scope s WHERE NOT EXISTS(SELECT 1 FROM dbo.test_payment_suppliers p WHERE p.supplier_id=s.supplier_id AND p.currency_code=s.currency) OR NOT EXISTS(SELECT 1 FROM dbo.test_payment_accounts a WHERE a.account_id=s.account_id AND a.opening_balance=1000) OR (s.invoice_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.test_payment_invoices v WHERE v.invoice_id=s.invoice_id))) THROW 51230,''WORK_PAYMENT_SOURCE_UNAVAILABLE'',1;
IF EXISTS(SELECT 1 FROM dbo.supplier_movements m JOIN dbo.work_finops_scope s ON s.supplier_id=m.supplier_id WHERE m.movement_type IN(N''payment'',N''payment_cancel'') AND NOT EXISTS(SELECT 1 FROM dbo.work_supplier_payment_requests j WHERE j.movement_id=m.id AND j.operation=m.movement_type) AND (s.currency=N''TRY'' OR NOT EXISTS(SELECT 1 FROM dbo.test_payment_requests old WHERE old.movement_id=m.id AND old.operation=m.movement_type))) THROW 51230,''WORK_PAYMENT_SOURCE_UNAVAILABLE'',1;
IF EXISTS(SELECT 1 FROM dbo.supplier_movements m JOIN dbo.work_finops_scope s ON s.supplier_id=m.supplier_id WHERE m.movement_type IN(N''payment'',N''payment_cancel'') AND (m.account_amount IS NULL OR m.account_currency IS NULL OR m.account_currency<>s.currency OR m.currency_code<>s.currency OR m.amount_try IS NULL OR m.document_exchange_rate_snapshot IS NULL OR m.account_exchange_rate_snapshot IS NULL OR (SELECT COUNT(*) FROM dbo.finance_account_movements f WHERE f.party_type=N''supplier'' AND f.party_movement_id=m.id AND f.source_type=m.movement_type)<>1 OR NOT EXISTS(SELECT 1 FROM dbo.finance_account_movements f WHERE f.party_type=N''supplier'' AND f.party_movement_id=m.id AND f.source_type=m.movement_type AND f.account_id=s.account_id AND f.currency_code=s.currency AND f.amount=m.account_amount AND f.direction=CASE m.movement_type WHEN N''payment'' THEN N''out'' ELSE N''in'' END))) THROW 51230,''WORK_PAYMENT_SOURCE_UNAVAILABLE'',1;
END;' AS nvarchar(max)),CHAR(13)+CHAR(10),CHAR(10)),CHAR(13),CHAR(10)); EXEC(@definition);
