SET @definition=REPLACE(REPLACE(CAST(N'CREATE PROCEDURE dbo.usp_work_supplier_payment_context @actor_id bigint WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON; EXEC dbo.usp_work_supplier_payment_ready; IF @actor_id IS NULL OR @actor_id<>16 OR NOT EXISTS(SELECT 1 FROM dbo.users u JOIN dbo.roles r ON r.id=u.role_id WHERE u.id=@actor_id AND u.is_active=1 AND r.is_active=1 AND r.code COLLATE Latin1_General_100_BIN2=N''isolated_test_ilker'') THROW 51230,''WORK_PAYMENT_SOURCE_UNAVAILABLE'',1;
IF (SELECT COUNT(*) FROM dbo.permissions p JOIN dbo.users u ON u.role_id=p.role_id JOIN dbo.roles r ON r.id=u.role_id WHERE u.id=@actor_id AND r.is_active=1 AND p.permission_key IN(N''finance.view'',N''supplier.view'') AND p.can_view=1)<>2 THROW 51230,''WORK_PAYMENT_SOURCE_UNAVAILABLE'',1;
SELECT (SELECT CONVERT(varchar(20),@actor_id) actorId,N''isolated_test_ilker'' roleCode,JSON_QUERY((SELECT N''[''+STRING_AGG(CONVERT(nvarchar(max),N''"''+STRING_ESCAPE(p.permission_key,''json'')+N''"''),N'','') WITHIN GROUP(ORDER BY p.permission_key)+N'']'' FROM dbo.permissions p JOIN dbo.users u ON u.role_id=p.role_id JOIN dbo.roles r ON r.id=u.role_id WHERE u.id=@actor_id AND r.is_active=1 AND p.can_view=1)) permissions,N''2026-10-06'' documentDate,N''500.0000'' maxAmountExact4,30 maxPayments,
JSON_QUERY((SELECT CONVERT(varchar(20),p.id) id,p.supplier_code code,p.name,p.currency_code currency,CONVERT(varchar(40),CAST(p.balance AS decimal(18,4))) balanceExact4,CAST(1 AS bit) snapshotVerified,s.debt_kind debtKind,JSON_QUERY((SELECT CONVERT(varchar(20),v.id) id,CONVERT(varchar(20),s.receipt_id) receiptId,N''work-finops-physical-receipt'' receiptKind,v.document_no number,v.status,CONVERT(char(10),v.document_date,23) documentDate,v.document_currency documentCurrency,CONVERT(varchar(40),CAST(v.grand_total AS decimal(18,4))) documentAmountExact4,v.account_currency accountCurrency,CONVERT(varchar(40),CAST(v.account_amount AS decimal(18,4))) accountAmountExact4,CONVERT(varchar(40),CAST(COALESCE((SELECT SUM(-m.balance_effect) FROM dbo.supplier_movements m WHERE m.purchase_invoice_id=v.id AND m.movement_type IN(N''payment'',N''payment_cancel'')),0) AS decimal(18,4))) paidExact4,N''0.0000'' returnedExact4,CONVERT(varchar(40),CAST(v.account_amount-COALESCE((SELECT SUM(-m.balance_effect) FROM dbo.supplier_movements m WHERE m.purchase_invoice_id=v.id AND m.movement_type IN(N''payment'',N''payment_cancel'')),0) AS decimal(18,4))) remainingExact4 FROM dbo.purchase_invoices v WHERE v.id=s.invoice_id FOR JSON PATH,INCLUDE_NULL_VALUES)) invoices FROM dbo.work_finops_scope s JOIN dbo.suppliers p ON p.id=s.supplier_id ORDER BY s.currency FOR JSON PATH,INCLUDE_NULL_VALUES)) suppliers,
JSON_QUERY((SELECT CONVERT(varchar(20),a.id) id,a.account_code code,a.account_name name,a.account_type type,a.currency_code currency,CONVERT(varchar(40),CAST(a.opening_balance AS decimal(18,4))) openingBalanceExact4,CONVERT(varchar(40),CAST(a.current_balance AS decimal(18,4))) balanceExact4,CAST(1 AS bit) openingVerified FROM dbo.work_finops_scope s JOIN dbo.finance_accounts a ON a.id=s.account_id ORDER BY s.currency FOR JSON PATH)) accounts,
JSON_QUERY((SELECT CONVERT(varchar(20),r.id) id,r.currency_code currency,CONVERT(varchar(40),CAST(r.rate_to_try AS decimal(18,8))) rateToTryExact8,CONVERT(char(10),r.rate_date,23) date FROM dbo.currency_rates r WHERE r.currency_code IN(N''USD'',N''EUR'') AND r.rate_date<=CONVERT(date,N''2026-10-06'') AND r.id=(SELECT TOP(1) x.id FROM dbo.currency_rates x WHERE x.currency_code=r.currency_code AND x.rate_date<=CONVERT(date,N''2026-10-06'') ORDER BY x.rate_date DESC,x.id DESC) ORDER BY r.currency_code FOR JSON PATH)) rates,
JSON_QUERY(COALESCE((SELECT CONVERT(varchar(20),m.id) id,CONVERT(varchar(20),m.supplier_id) supplierId,CONVERT(varchar(20),f.account_id) accountId,CONVERT(varchar(20),m.purchase_invoice_id) invoiceId,CONVERT(varchar(20),s.receipt_id) receiptId,CASE WHEN s.receipt_id IS NULL THEN NULL ELSE N''work-finops-physical-receipt'' END receiptKind,v.document_no invoiceNumber,m.movement_type kind,f.direction,m.currency_code currency,CONVERT(varchar(40),CAST(m.amount AS decimal(18,4))) amountExact4,m.account_currency accountCurrency,CONVERT(varchar(40),CAST(m.account_amount AS decimal(18,4))) accountAmountExact4,CONVERT(varchar(40),CAST(m.amount_try AS decimal(18,4))) amountTryExact4,CONVERT(varchar(40),CAST(m.document_exchange_rate_snapshot AS decimal(18,8))) documentRateExact8,CONVERT(varchar(40),CAST(m.account_exchange_rate_snapshot AS decimal(18,8))) accountRateExact8,CONVERT(char(10),m.document_date,23) documentDate,COALESCE(f.description,N'''') description,f.document_no number,CONVERT(varchar(20),j.original_id) originalId,CONVERT(varchar(20),cancel.movement_id) reversedById,j.ownership,CAST(CASE WHEN j.ownership=N''work'' AND m.movement_type=N''payment'' AND cancel.movement_id IS NULL THEN 1 ELSE 0 END AS bit) canCancel FROM (SELECT movement_id,original_id,N''work'' ownership FROM dbo.work_supplier_payment_requests UNION ALL SELECT j.movement_id,j.original_id,N''legacy'' ownership FROM dbo.test_payment_requests j JOIN dbo.supplier_movements old ON old.id=j.movement_id WHERE old.supplier_id IN(13371,13372) AND j.operation IN(N''payment'',N''payment_cancel'')) j JOIN dbo.supplier_movements m ON m.id=j.movement_id JOIN dbo.work_finops_scope s ON s.supplier_id=m.supplier_id JOIN dbo.finance_account_movements f ON f.party_type=N''supplier'' AND f.party_movement_id=m.id AND f.source_type=m.movement_type LEFT JOIN dbo.purchase_invoices v ON v.id=m.purchase_invoice_id LEFT JOIN (SELECT movement_id,original_id,N''work'' ownership FROM dbo.work_supplier_payment_requests UNION ALL SELECT j.movement_id,j.original_id,N''legacy'' ownership FROM dbo.test_payment_requests j JOIN dbo.supplier_movements old ON old.id=j.movement_id WHERE old.supplier_id IN(13371,13372) AND j.operation IN(N''payment'',N''payment_cancel'')) cancel ON cancel.original_id=m.id ORDER BY m.id FOR JSON PATH,INCLUDE_NULL_VALUES),N''[]'')) payments
FOR JSON PATH,WITHOUT_ARRAY_WRAPPER) context_json,CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.usp_work_supplier_payment_ready''))),2) readyHash,CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.usp_work_supplier_payment_context''))),2) contextHash,CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.usp_work_supplier_payment_effects''))),2) effectsHash;
END;' AS nvarchar(max)),CHAR(13)+CHAR(10),CHAR(10)),CHAR(13),CHAR(10)); EXEC(@definition);
INSERT dbo.work_finops_manifest(name,definition_hash) VALUES(N'usp_work_supplier_payment_context',N'4C5DB1E8398401818BB6977E9AF3B05FD83D40F81658A78907015E7B8FC79C18');
SET @definition=REPLACE(REPLACE(CAST(N'CREATE PROCEDURE dbo.usp_work_supplier_payment_effects @request_id uniqueidentifier WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON; EXEC dbo.usp_work_supplier_payment_ready;
IF @request_id IS NULL OR NOT EXISTS(SELECT 1 FROM dbo.work_supplier_payment_requests WHERE request_id=@request_id) THROW 51230,''WORK_PAYMENT_SOURCE_UNAVAILABLE'',1;
IF (SELECT COUNT(*) FROM dbo.work_supplier_payment_requests WHERE operation=N''payment'')>30 THROW 51230,''WORK_PAYMENT_SOURCE_UNAVAILABLE'',1;
IF EXISTS(SELECT 1 FROM dbo.work_supplier_payment_requests j JOIN dbo.supplier_movements m ON m.id=j.movement_id JOIN dbo.work_finops_scope s ON s.supplier_id=m.supplier_id WHERE JSON_VALUE(j.response_json,''$.requestId'') IS NULL OR JSON_VALUE(j.response_json,''$.requestId'') COLLATE Latin1_General_100_BIN2<>LOWER(CONVERT(varchar(36),j.request_id)) COLLATE Latin1_General_100_BIN2 OR JSON_VALUE(j.response_json,''$.replayed'') IS NULL OR JSON_VALUE(j.response_json,''$.replayed'')<>N''false'' OR JSON_VALUE(j.response_json,''$.payment.ownership'') IS NULL OR JSON_VALUE(j.response_json,''$.payment.ownership'')<>N''work'' OR EXISTS(SELECT TRY_CONVERT(bigint,JSON_VALUE(j.response_json,''$.payment.supplierId'')),TRY_CONVERT(bigint,JSON_VALUE(j.response_json,''$.payment.accountId'')),TRY_CONVERT(bigint,JSON_VALUE(j.response_json,''$.payment.invoiceId'')),TRY_CONVERT(bigint,JSON_VALUE(j.response_json,''$.payment.receiptId'')),TRY_CONVERT(decimal(18,4),JSON_VALUE(j.response_json,''$.payment.amountExact4'')),TRY_CONVERT(decimal(18,4),JSON_VALUE(j.response_json,''$.payment.accountAmountExact4'')),TRY_CONVERT(decimal(18,4),JSON_VALUE(j.response_json,''$.payment.amountTryExact4'')),TRY_CONVERT(decimal(18,8),JSON_VALUE(j.response_json,''$.payment.documentRateExact8'')),TRY_CONVERT(decimal(18,8),JSON_VALUE(j.response_json,''$.payment.accountRateExact8'')) EXCEPT SELECT m.supplier_id,s.account_id,m.purchase_invoice_id,s.receipt_id,m.amount,m.account_amount,m.amount_try,m.document_exchange_rate_snapshot,m.account_exchange_rate_snapshot) OR m.document_date<>CONVERT(date,N''2026-10-06'') OR TRY_CONVERT(date,JSON_VALUE(j.payload_json,''$.documentDate'')) IS NULL OR TRY_CONVERT(date,JSON_VALUE(j.payload_json,''$.documentDate''))<>m.document_date OR(s.currency=N''TRY'' AND m.document_exchange_rate_snapshot<>1)) THROW 51230,''WORK_PAYMENT_SOURCE_UNAVAILABLE'',1;
IF EXISTS(SELECT 1 FROM dbo.work_supplier_payment_requests j LEFT JOIN dbo.supplier_movements m ON m.id=j.movement_id LEFT JOIN dbo.work_finops_scope s ON s.supplier_id=m.supplier_id WHERE m.id IS NULL OR s.supplier_id IS NULL OR m.created_by<>16 OR m.created_by IS NULL OR m.movement_type<>j.operation OR m.amount IS NULL OR m.amount<=0 OR m.amount>500 OR m.currency_code<>s.currency OR m.account_currency IS NULL OR m.account_currency<>s.currency OR m.account_amount IS NULL OR m.account_amount<>m.amount OR m.amount_try IS NULL OR m.document_exchange_rate_snapshot IS NULL OR m.account_exchange_rate_snapshot IS NULL OR m.document_exchange_rate_snapshot<=0 OR m.account_exchange_rate_snapshot<>m.document_exchange_rate_snapshot OR m.amount_try<>CAST(m.amount*m.document_exchange_rate_snapshot AS decimal(18,4)) OR m.balance_effect<>CASE j.operation WHEN N''payment'' THEN -m.account_amount ELSE m.account_amount END OR (s.debt_kind=N''opening'' AND m.purchase_invoice_id IS NOT NULL) OR(s.debt_kind=N''invoice'' AND (m.purchase_invoice_id IS NULL OR m.purchase_invoice_id<>s.invoice_id)) OR (SELECT COUNT(*) FROM dbo.finance_account_movements f WHERE f.party_type=N''supplier'' AND f.party_movement_id=m.id AND f.source_type=m.movement_type)<>1 OR NOT EXISTS(SELECT 1 FROM dbo.finance_account_movements f WHERE f.party_type=N''supplier'' AND f.party_movement_id=m.id AND f.source_type=m.movement_type AND f.account_id=s.account_id AND f.amount=m.account_amount AND f.currency_code=m.account_currency AND f.direction=CASE j.operation WHEN N''payment'' THEN N''out'' ELSE N''in'' END AND f.created_by=16) OR NOT EXISTS(SELECT 1 FROM dbo.audit_logs a WHERE a.entity_type=N''supplier_movement'' AND a.entity_id=m.id AND a.actor_user_id=16)) THROW 51230,''WORK_PAYMENT_SOURCE_UNAVAILABLE'',1;
IF EXISTS(SELECT 1 FROM dbo.work_supplier_payment_requests j JOIN dbo.supplier_movements m ON m.id=j.movement_id WHERE j.operation=N''payment'' AND (TRY_CONVERT(bigint,JSON_VALUE(j.payload_json,''$.supplierId'')) IS NULL OR TRY_CONVERT(bigint,JSON_VALUE(j.payload_json,''$.supplierId''))<>m.supplier_id OR TRY_CONVERT(bigint,JSON_VALUE(j.payload_json,''$.accountId'')) IS NULL OR NOT EXISTS(SELECT 1 FROM dbo.work_finops_scope s WHERE s.supplier_id=m.supplier_id AND s.account_id=TRY_CONVERT(bigint,JSON_VALUE(j.payload_json,''$.accountId''))) OR JSON_VALUE(j.payload_json,''$.amountExact4'') IS NULL OR TRY_CONVERT(decimal(18,4),JSON_VALUE(j.payload_json,''$.amountExact4'')) IS NULL OR TRY_CONVERT(decimal(18,4),JSON_VALUE(j.payload_json,''$.amountExact4''))<>m.amount OR JSON_VALUE(j.payload_json,''$.currency'') IS NULL OR JSON_VALUE(j.payload_json,''$.currency'')<>m.currency_code OR TRY_CONVERT(date,JSON_VALUE(j.payload_json,''$.documentDate'')) IS NULL OR TRY_CONVERT(date,JSON_VALUE(j.payload_json,''$.documentDate''))<>m.document_date OR EXISTS(SELECT TRY_CONVERT(bigint,JSON_VALUE(j.payload_json,''$.invoiceId'')) EXCEPT SELECT m.purchase_invoice_id))) THROW 51230,''WORK_PAYMENT_SOURCE_UNAVAILABLE'',1;
IF EXISTS(SELECT 1 FROM dbo.work_supplier_payment_requests j JOIN dbo.supplier_movements m ON m.id=j.movement_id LEFT JOIN dbo.work_supplier_payment_requests original ON original.movement_id=j.original_id AND original.operation=N''payment'' LEFT JOIN dbo.supplier_movements o ON o.id=original.movement_id WHERE j.operation=N''payment_cancel'' AND (o.id IS NULL OR TRY_CONVERT(bigint,JSON_VALUE(j.payload_json,''$.id'')) IS NULL OR TRY_CONVERT(bigint,JSON_VALUE(j.payload_json,''$.id''))<>o.id OR EXISTS(SELECT m.supplier_id,m.purchase_invoice_id,m.amount,m.currency_code,m.account_currency,m.account_amount,m.amount_try,m.document_exchange_rate_snapshot,m.account_exchange_rate_snapshot EXCEPT SELECT o.supplier_id,o.purchase_invoice_id,o.amount,o.currency_code,o.account_currency,o.account_amount,o.amount_try,o.document_exchange_rate_snapshot,o.account_exchange_rate_snapshot))) THROW 51230,''WORK_PAYMENT_SOURCE_UNAVAILABLE'',1;
IF EXISTS(SELECT 1 FROM dbo.work_finops_scope s JOIN dbo.suppliers p ON p.id=s.supplier_id JOIN dbo.finance_accounts a ON a.id=s.account_id WHERE p.balance<0 OR p.balance>300 OR a.current_balance<0 OR a.current_balance>1000 OR (s.invoice_id IS NOT NULL AND COALESCE((SELECT SUM(-m.balance_effect) FROM dbo.supplier_movements m WHERE m.purchase_invoice_id=s.invoice_id AND m.movement_type IN(N''payment'',N''payment_cancel'')),0) NOT BETWEEN 0 AND 300)) THROW 51230,''WORK_PAYMENT_SOURCE_UNAVAILABLE'',1;
SELECT CAST(1 AS bit) valid,CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.usp_work_supplier_payment_ready''))),2) readyHash,CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.usp_work_supplier_payment_context''))),2) contextHash,CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.usp_work_supplier_payment_effects''))),2) effectsHash;
